use xiom.io;

type Hero = {
  name: Str;
  hp: Int;
  gold: Int;
}

enum Monster {
  Goblin,
  Skeleton,
  Dragon,
}

enum Action {
  Attack,
  Defend,
  UseItem(item: Str),
}

fn Monster.power(self) -> Int {
  match self {
    Goblin => { return 5; }
    Skeleton => { return 8; }
    Dragon => { return 20; }
  }
}

fn Hero.take_damage(self, amount: Int) {
  hp = hp - amount;
  if hp < 0 { hp = 0; }
}

fn Monster.gold_reward(self) -> Int {
  match self {
    Goblin => { return 10; }
    Skeleton => { return 25; }
    Dragon => { return 100; }
  }
}

fn battle(hero: Hero, monster: Monster, action: Action) -> Str {
  let power = monster.power();
  match action {
    Attack => {
      hero.take_damage(power);
      return hero.name + " attacks the monster! Hero HP: " + hero.hp;
    }
    Defend => {
      var reduced = power / 2;
      hero.take_damage(reduced);
      return hero.name + " defends! Hero HP: " + hero.hp;
    }
    UseItem(item) => {
      if item == "Healing Potion" {
        hero.hp = hero.hp + 20;
        return hero.name + " uses " + item + "! Hero HP: " + hero.hp;
      }
      return hero.name + " used " + item;
    }
  }
}

fn main() -> Int {
  var hero = Hero{ name: "Aria"; hp: 30; gold: 100; };
  let goblin = Monster.Goblin;
  battle(hero, goblin, Action.Attack);
  return hero.hp;
}
